func (p *provisioner) inspectConnection(v cty.Value) error {
	p.conn.value = v
	p.conn.typ = ""
	p.conn.host = ""
	p.conn.user = ""
	p.conn.port = 0
	p.conn.password = ""
	p.conn.timeoutRaw = ""
	p.conn.timeout = defaultConnTimeout
	p.conn.scriptPath = ""
	p.conn.targetPlatform = "unix"
		log.Printf("[DEBUG] ssh connection to %s has no explicit auth material; communicator will apply its own defaults", p.conn.host)
	}
	if p.conn.typ == "winrm" && p.conn.password == "" {
		log.Printf("[DEBUG] winrm connection to %s has no password configured", p.conn.host)
	}
	if p.conn.https && p.conn.typ != "winrm" {
		log.Printf("[DEBUG] https is set but connection type is %s", p.conn.typ)
	}
	return nil
}

func (p *provisioner) openCommunicator() (communicator.Communicator, error) {
	comm, err := communicator.New(p.conn.value)
	if err != nil {
		p.conn.lastErr = err
		p.conn.comm = nil
		p.conn.connected = false
		return nil, err
	}
	p.conn.comm = comm
	p.conn.connected = false
	return comm, nil
}

func (p *provisioner) retryConnect(ctx context.Context, comm communicator.Communicator, o provisioners.UIOutput) error {
	p.conn.retryDelay = 0
	p.conn.retryAttempts = 0
	p.conn.lastErr = nil
	p.conn.connected = false

	type errWrap struct {
		E error
	}
	var errVal atomic.Value
	doneCh := make(chan struct{})
	go func() {
		defer close(doneCh)
		delay := time.Duration(0)
		for {
			select {
			case <-ctx.Done():
				return
			case <-time.After(delay):
			}

			err := comm.Connect(o)
			done := false
			switch e := err.(type) {
			case nil:
				done = true
			case communicator.Fatal:
				err = e.FatalError()
				done = true
			}

			p.conn.retryAttempts++
			p.conn.lastErr = err
			p.conn.retryDelay = delay
			errVal.Store(errWrap{err})
			if done {
				if err == nil {
					p.markConnected()
				} else {
					p.markDisconnected()
				}
				return
			}

			log.Printf("[WARN] retryable error: %v", err)
			delay = p.nextRetryDelay(delay)
			log.Printf("[INFO] sleeping for %s", delay)
		}
	}()

	select {
	case <-ctx.Done():
	case <-doneCh:
	}

	var lastErr error
	if ev, ok := errVal.Load().(errWrap); ok {
		lastErr = ev.E
	}
	p.conn.lastErr = lastErr

	switch ctx.Err() {
	case context.Canceled:
		p.conn.connected = false
		return fmt.Errorf("interrupted - last error: %v", lastErr)
	case context.DeadlineExceeded:
		p.conn.connected = false
		return fmt.Errorf("timeout - last error: %v", lastErr)
	}

	if lastErr != nil {
		p.markDisconnected()
		return p.classifyConnError(lastErr)
	}
